(* Linear scaling of the 4-20mA raw signal to engineering units. *)
PV := Raw_Signal * Scaling_Slope + Scaling_Offset;
(* Wire-break style fault: a healthy 4-20mA loop never drops below ~2mA. *)
General_Fault := Alarm_Enable AND (Raw_Signal < 2.0);
High_Alarm := Alarm_Enable AND (PV > PV_High);
Low_Alarm := Alarm_Enable AND (PV < PV_Low);

Bool_Out := Bool_In;
Alarm_Active := (Alarm_OnTrue AND Bool_In) OR (Alarm_OnFalse AND NOT Bool_In);
IF Reset_Latch THEN
    Latched_Status := FALSE;
ELSIF Latch_Enable AND Alarm_Active THEN
    Latched_Status := TRUE;
END_IF;

(* Pass-through of the field contact (debounce not modeled). *)
DI_Out := DI_Raw;
Fault_State := FALSE;

ActiveIsA := NOT AlternateEnable;
IF Enable AND StartRequest AND NOT Inhibit THEN
    CmdPumpA := ActiveIsA AND NOT PumpA_Fault;
    CmdPumpB := (NOT ActiveIsA OR PumpA_Fault) AND NOT PumpB_Fault;
ELSE
    CmdPumpA := FALSE;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpA THEN
    CmdPumpA := Enable AND NOT Inhibit;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpB THEN
    CmdPumpA := FALSE;
    CmdPumpB := Enable AND NOT Inhibit;
END_IF;
SwitchedDueToDuty := DutyElapsed;
SwitchedDueToFailure := PumpA_Fault OR PumpB_Fault;
Alarm_FailedStart_A := PumpA_Fault;
Alarm_FailedStart_B := PumpB_Fault;
Alarm_NoAvailablePump := PumpA_Fault AND PumpB_Fault;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_HighSpeed := Motor_Start_Out AND Speed_High_Cmd;
FB_LowSpeed := Motor_Start_Out AND Speed_Low_Cmd AND NOT Speed_High_Cmd;
FB_Trip := FALSE;
Alarm_Speed_Error := Speed_High_Cmd AND Speed_Low_Cmd;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_Trip := FALSE;
Alarm_Start_Fail := FALSE;
Alarm_Stop_Fail := FALSE;

IF Inhibit OR Stop_Cmd THEN
    FB_Running := FALSE;
ELSIF Start_Cmd THEN
    FB_Running := TRUE;
END_IF;
IF FB_Running THEN
    Speed_Out := Speed_SP;
ELSE
    Speed_Out := 0.0;
END_IF;
FB_Ready := NOT Inhibit;
FB_Fault := FALSE;
FB_ActualSpeed := Speed_Out;
Alarm_Speed_Deviation := FALSE;
Alarm_Comm_Fail := FALSE;

PV_High_Alarm := PV > PV_High;
PV_Low_Alarm := PV < PV_Low;
Deviation_Alarm := ABS(SP - PV) > Deviation_Limit;
(* Bounded proportional control law (single-block, stateless). *)
IF Inhibit THEN
    XOUT := MV_MIN;
ELSIF AUTO THEN
    XOUT := LIMIT(MV_MIN, X0 + KP * (SP - PV), MV_MAX);
ELSE
    XOUT := X0;
END_IF;

IF PrimaryPV > 0.0 THEN
    ActiveRatio := SecondaryPV / PrimaryPV;
ELSE
    ActiveRatio := 0.0;
END_IF;
RatioErr := ActiveRatio - RatioSP;
IF Inhibit THEN
    SlaveSP := MV_MIN;
ELSIF Auto THEN
    SlaveSP := LIMIT(MV_MIN, PrimaryPV * RatioSP + Bias, MV_MAX);
ELSE
    SlaveSP := ManOut;
END_IF;

IF IN <= Split_Point THEN
    OUT1 := Output1_End;
    OUT2 := Output2_Start;
ELSE
    OUT1 := Output1_Start;
    OUT2 := Output2_End;
END_IF;

IF Inhibit THEN
    Valve_Position := Close_Limit;
ELSIF Manual_Mode THEN
    Valve_Position := LIMIT(Close_Limit, Manual_Position, Open_Limit);
ELSE
    Valve_Position := LIMIT(Close_Limit, Control_Signal, Open_Limit);
END_IF;
Feedback_Pos := Valve_Position;
Valve_Moving := FALSE;
Position_Error := FALSE;
Alarm := Inhibit;

IF Inhibit THEN
    Valve_Open_Out := FALSE;
    Valve_Close_Out := TRUE;
ELSE
    Valve_Open_Out := Open_Cmd AND NOT Close_Cmd;
    Valve_Close_Out := Close_Cmd OR NOT Open_Cmd;
END_IF;
FB_Opened := Valve_Open_Out;
FB_Closed := NOT Valve_Open_Out;
Alarm_Position_Error := FALSE;
Alarm_General := Inhibit;

Voted_Output := (Input1 + Input2 + Input3) / 3.0;
Sensor1_Fault := FALSE;
Sensor2_Fault := FALSE;
Sensor3_Fault := FALSE;
Alarm_Voting_Error := FALSE;
Healthy_Sensors_Count := 3;

DP_101(
    Alarm_Enable := TRUE);
DP_102(
    Alarm_Enable := TRUE);
FT_101(
    Scaling_Slope := 312.5,
    Scaling_Offset := -1250.0,
    Alarm_Enable := TRUE);
IT_102(
    Scaling_Slope := 125.0,
    Scaling_Offset := -500.0,
    Alarm_Enable := TRUE);
LT_101(
    Alarm_Enable := TRUE);
IIC101_Inhibit_OR := LT_101.High_Alarm OR FT_101.Low_Alarm OR DP_101.High_Alarm OR DP_102.High_Alarm;
IIC_101(
    Auto := TRUE,
    PrimaryPV := FT_101.PV,
    SecondaryPV := IT_102.PV,
    RatioSP := 2.5,
    Bias := 0.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    Inhibit := IIC101_Inhibit_OR);
LCV101_Inhibit_OR := FT_101.Low_Alarm OR IT_102.High_Alarm OR IT_102.Low_Alarm OR DP_101.High_Alarm OR DP_102.High_Alarm;
LCV_101(
    Control_Signal := IIC_101.SlaveSP,
    Manual_Mode := FALSE,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := LCV101_Inhibit_OR);

(* Outputs published to other sections / HMI. *)
FT_101_Flow_PV := FT_101.PV;
IT_102_Flow_PV := IT_102.PV;
DP_101_DiffP_PV := DP_101.PV;
DP_102_DiffP_PV := DP_102.PV;
LT_101_Level_PV := LT_101.PV;
IIC_101_LiqSepFlow_SP := IIC_101.SlaveSP;

AI_201(
    Alarm_Enable := TRUE);
LT_201(
    Alarm_Enable := TRUE);
PT_201(
    PV_Low := 0.5,
    Alarm_Enable := TRUE);
TT_201(
    PV_High := 50.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
TIC201_Inhibit_OR := TT_201.High_Alarm OR PT_201.Low_Alarm OR AI_201.High_Alarm OR TT_201.General_Fault;
FV101_Inhibit_OR := TIC201_Inhibit_OR OR LT_201.Low_Alarm;
FV_101(
    Control_Signal := TIC_201.XOUT,
    Manual_Mode := FALSE,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := FV101_Inhibit_OR);
TIC_201(
    AUTO := TRUE,
    PV := TT_201.PV,
    SP := 45.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := FV_101.Feedback_Pos,
    KP := 3.0,
    TR := 1.5,
    TD := 0.0,
    Deviation_Limit := 5.0,
    Inhibit := TIC201_Inhibit_OR);

(* Outputs published to other sections / HMI. *)
TT201_Temperature_PV := TT_201.PV;
PT201_FlashTankPressure_PV := PT_201.PV;
LT201_AbsorberLevel_PV := LT_201.PV;
AI201_CO2_PV := AI_201.PV;
TIC201_MV_SteamValveCmd := TIC_201.XOUT;

AI_302(
    Alarm_Enable := TRUE);
AI_303(
    Alarm_Enable := TRUE);
AI_304(
    PV_High := 10.0,
    Alarm_Enable := TRUE);
DI_301();
DP_301(
    PV_High := 20.0,
    Alarm_Enable := TRUE);
FT_301(
    PV_Low := 500.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
Inhibit_OR := AI_302.High_Alarm OR AI_303.High_Alarm OR AI_302.General_Fault OR AI_303.General_Fault OR DI_301.DI_Out OR FT_301.Low_Alarm OR DP_301.High_Alarm;
FFIC_303(
    Auto := TRUE,
    PrimaryPV := FT_301.PV,
    RatioSP := 0.25,
    Bias := 0.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    Inhibit := Inhibit_OR);
FIC_302(
    AUTO := TRUE,
    SP := FFIC_303.SlaveSP,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    Inhibit := Inhibit_OR);
FV_302(
    Control_Signal := FIC_302.XOUT,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := Inhibit_OR);

(* Outputs published to other sections / HMI. *)
AI302_H2O_Outlet_PV := AI_302.PV;
AI303_Hg_Permissive_PV := AI_303.PV;
AI304_H2O_RatioOpt_PV := AI_304.PV;
FT301_FeedGasFlow_PV := FT_301.PV;
DP301_MolSieveBed_DP_PV := DP_301.PV;
FFIC303_RegenFlow_SP_to_FIC302 := FFIC_303.SlaveSP;

FV_501(
    Open_Limit := 100.0);
FV501_FullyOpen_GT := (FV_501.Feedback_Pos > 99.0);
FV501_Open_TON(
    IN := FV501_FullyOpen_GT,
    PT := T#5s);
FT_501(
    Scaling_Slope := 312.5,
    Scaling_Offset := -1250.0,
    Alarm_Enable := TRUE);
LowFlowCutoff_LT := (FT_501.PV < 500.0);
AutoDisable1_OR := LowFlowCutoff_LT OR FV501_Open_TON.Q;
FT501_RangeAlarm_OR := FT_501.Low_Alarm OR FT_501.High_Alarm;
FT_502(
    Scaling_Slope := 125.0,
    Scaling_Offset := -500.0,
    Alarm_Enable := TRUE);
FT502_RangeAlarm_OR := FT_502.Low_Alarm OR FT_502.High_Alarm;
FlowRangeViolation_OR := FT501_RangeAlarm_OR OR FT502_RangeAlarm_OR;
FlowSignalFault_OR := FT_501.General_Fault OR FT_502.General_Fault;
AnySignalIssue_OR := FlowRangeViolation_OR OR FlowSignalFault_OR;
PT_501(
    Alarm_Enable := TRUE);
SafetyCommon_OR := PT_501.Low_Alarm OR AnySignalIssue_OR;
AutoDisable3_OR := AutoDisable1_OR OR SafetyCommon_OR;
AutoMode_NOT := NOT AutoDisable3_OR;
ManualSP_SEL1 := SEL(G := FV501_Open_TON.Q, IN0 := 100.0, IN1 := 1000.0);
ManualSP_SEL2 := SEL(G := AnySignalIssue_OR, IN0 := ManualSP_SEL1, IN1 := 500.0);
TIT_102(
    PV_High := -155.0,
    Alarm_Enable := TRUE);
TempHigh_GT := (TIT_102.PV > -155.0);
AutoTrim_SEL := SEL(G := TempHigh_GT, IN0 := 0.0, IN1 := 0.1);
RatioSum_ADD := 2.5 + AutoTrim_SEL;
RatioBias_ADD := RatioSum_ADD + Operator_RatioBias;
RatioClamp_LIMIT := LIMIT(MN := 2.0, IN := RatioBias_ADD, MX := 3.0);
FFIC_503(
    Auto := AutoMode_NOT,
    PrimaryPV := FT_501.PV,
    SecondaryPV := FT_502.PV,
    RatioSP := RatioClamp_LIMIT,
    ManOut := ManualSP_SEL2,
    Inhibit := SafetyCommon_OR);
FIC_504(
    PV := FT_502.PV,
    SP := FFIC_503.SlaveSP,
    Inhibit := FlowSignalFault_OR);
FV_502(
    Control_Signal := FIC_504.XOUT);
RatioDevHi_GT := (FFIC_503.RatioErr > 0.2);
RatioDevHi_TON(
    IN := RatioDevHi_GT,
    PT := T#10s);
RatioDevLo_LT := (FFIC_503.RatioErr < -0.2);
RatioDevLo_TON(
    IN := RatioDevLo_LT,
    PT := T#10s);

(* Outputs published to other sections / HMI. *)
FFIC503_DV_HI := RatioDevHi_TON.Q;
FFIC503_DV_LO := RatioDevLo_TON.Q;
FT501_PropaneFlow_PV := FT_501.PV;
FT502_MRFlow_PV := FT_502.PV;
PT501_EndFlashDrumPressure_PV := PT_501.PV;
TIT102_MCHE_OutletTemp_PV := TIT_102.PV;
FIC504_MRFlow_SP_From_FFIC503 := FFIC_503.SlaveSP;
FFIC503_ActiveRatio := FFIC_503.ActiveRatio;
